      "stem": "资产组含A、B两台机器，账面价值60万元和40万元，组可收回金额70万元，无商誉。A可单独确定处置净额55万元，B单独金额不能确定；其他下限均为零。要求分摊30万元减值并解释为何不能直接按60:40最终分配。",
