      "sample": "(a)现时义务且很可能流出、可可靠计量，确认预计负债50万元。\n(b)可撤销意向不构成现时义务，不确认预计负债。\n(c)可能但未达到很可能，通常作为或有负债披露，不确认40万元负债。\n未来经营亏损不是由过去事项形成的现时义务，不能据此确认预计负债30万元。",
      "explain": "先检验现时义务，再看流出概率和可靠计量，不能见风险就提负债。披露与确认是不同层次。",
