      "type": "written",
      "stem": "顺成公司为居民企业，年度会计利润总额120万元，销售收入1000万元，已计入费用的业务招待费18万元。题设扣除规则：发生额60%，且不超过销售收入5‰，按较低者扣除。适用企业所得税率25%，无其他调整、亏损、免税或优惠。要求：（1）计算允许扣除及调增额；（2）计算应纳税所得额与所得税。",
      "sample": "（1）发生额限额=18×60%=10.8万元；收入限额=1000×5‰=5万元，允许扣除5万元，调增18−5=13万元。（2）应纳税所得额=120+13=133万元；所得税=133×25%=33.25万元。",
      "explain": "利润中已经扣除了全部18万元，因此只调增不允许部分。易错点：两个限额取较小值，不是相加；5‰是0.5%而非5%；不能把允许扣除额5万元再从已扣过费用的利润中重复扣除。",
      "rubric": [
        "双限额10.8与5且取5",
        "调增13所得133",
        "税额33.25"
      ],
