      "stem": "甲烟草企业收购烟叶，支付收购价款100000元。题设按收购价款10%计入价外补贴，烟叶税率20%，无减免。另一个独立境内业务本月实际缴增值税20000元、消费税5000元，均构成附加依据；进口税7000元不构成附加依据。适用城建税7%、教育费附加3%、地方教育附加2%，无其他调整。要求：（1）确定烟叶税纳税主体及税基；（2）计算烟叶税；（3）计算独立业务三项附加，说明烟叶税是否直接加入两税依据。",
