      "type": "written",
      "stem": "甲居民企业为一般纳税人，本期购入机器价税合计113万元，增值税13%，取得合规抵扣凭证且全用于可抵扣业务。本期其他业务销项30万元，期初留抵2万元，仅有上述进项。境内增值税本期实际缴纳，城建7%、教育3%、地方教育2%。购机合同单列价款100万元和增值税13万元，买卖印花税0.03%。年度会计利润100万元已扣全部合法附加及印花税；机器账面折旧20万元、税前折旧10万元，其他无调整，所得税25%。要求：（1）算本期增值税；（2）算附加和合同印花税；（3）算年度所得税。",
