      "type": "written",
      "stem": "居民个人小江全年境内工资180000元、境外劳务报酬20000元。题设劳务收入额按80%计；全年基本费用60000元、专项扣除24000元、专项附加扣除12000元；全年所得按我国综合所得规则合并，税率表36000以内3%，超过36000至144000元10%、速算2520元。本题经依法计算的境外抵免限额1600元，境外可抵免实缴800元；境内已预扣6000元。题设本期完成申报缴款，无逾期。要求：（1）算合并收入额和应税所得；（2）算年度税及境外抵免后应负税额；（3）算应补退并列示申报凭证。",
      "sample": "（1）境外劳务收入额=20000×80%=16000元，合计196000元；应税所得=196000−60000−24000−12000=100000元。（2）年度税=100000×10%−2520=7480元；可抵免min(800,1600)=800元，抵免后6680元。（3）应补6680−6000=680元；保存收入分类、境外完税和限额计算资料、扣除依据及预扣记录。",
      "explain": "境内外综合所得按题设统一计算，境外税额在计算我国年度税后抵免，再扣境内预扣。易错点：境外劳务收入不是天然免税；1600元限额不等于实际能抵1600元；境外税款不再作为综合所得扣除；本题无逾期不能额外加滞纳金。",
