      "stem": "甲一般纳税人企业全年出租商用办公房，按一般计税取得含增值税租金109万元，增值税率9%，本年度合规可抵扣进项3万元，无留抵。房产税从租税率12%。租赁合同分别列示不含税租金100万元、增值税9万元，租赁印花税率0.1%。境内增值税实际缴纳，城建7%、教育3%、地方教育2%；题设排除所有税费优惠，无其他业务。要求：（1）算应缴增值税；（2）算房产税、印花税；（3）算三项附加和本题所列税费合计，解释税基差别。",
