      "explain": "同一交易可触及多个税种，各自按租金、应税合同或实缴两税计税。易错点：房产税不以增值税应纳6万元为税基；商用房不能套个人住房出租优惠；印花税排除已单列增值税；本题仅所列税费，不包含所得税等未要求税种。",
