      "chapterIndex": 9,
      "practiceStage": "cross",
      "knowledgePoint": "房地产转让双方、土地增值税与企业所得税",
      "type": "written",
      "stem": "甲居民企业向乙企业转让商业房产，不含增值税价1000万元。题设土地增值税全部合法扣除项目600万元；增值率超过50%至100%适用40%税率、5%速算系数，无减免。产权转移印花税率0.05%，合同单列增值税，甲乙各按1000万元缴。乙契税率3%。甲的所得税转让收入1000万元，可扣资产成本及其他费用700万元（不含本次土地增值税和印花税），两税依法可扣，企业所得税25%。本题不计算增值税及附加。要求：（1）算甲土地增值税；（2）算双方印花税及乙契税；（3）算甲本项所得税。",
      "sample": "（1）增值额400万元，增值率400÷600=66.6667%；土地增值税=400×40%−600×5%=130万元。（2）甲乙印花税各1000×0.05%=0.5万元；乙契税=1000×3%=30万元。（3）甲应税所得=1000−700−130−0.5=169.5万元；所得税=169.5×25%=42.375万元。",
      "explain": "先分转让与受让主体，土地增值税扣除口径和所得税成本口径各依题设；所得税扣除甲自身税款，不能扣乙的契税。易错点：5%系数乘扣除600不是收入1000；甲乙印花税不能一方缴完替代另一方；不添加题设排除的增值税附加。",
      "rubric": [
        "增值400率66.6667土地税130",
        "双方印花各0.5乙契税30",
        "所得169.5税42.375",
        "主体和扣除口径清楚"
      ],
