      "chapterIndex": 7,
      "practiceStage": "cross",
      "knowledgePoint": "矿产品增值税、资源税、环保税与所得税",
      "type": "written",
      "stem": "甲矿业居民企业为一般纳税人，本期销售自产应税矿产品含增值税收入113万元，增值税13%，合规可抵扣进项5万元，无留抵；资源税从价6%。直接排放单一应税污染物500千克，当量值0.5千克/污染当量，适用1.2元/当量，无减免和排序问题。境内增值税实缴，城建7%、教育3%、地方教育2%。年度会计利润20万元已正确扣除本题资源税、环保税及附加，所得税25%，无其他调整。要求：（1）算增值税与资源税；（2）算环保税与附加；（3）算所得税并说明不可重复扣除。",
      "sample": "（1）不含税销售100万元，增值税=13−5=8万元，资源税=100×6%=6万元。（2）污染当量1000，环保税1200元即0.12万元；附加=8×12%=0.96万元，其中0.56、0.24、0.16。（3）应税所得20万元，所得税=20×25%=5万元。资源税环保税附加已经入账扣除且税法允许，不能从20万元再扣一次。",
      "explain": "逐项核对税基：销售、污染当量、实缴增值税、会计利润。易错点：资源税和环保税不是城建附加“两税”；用千克直接乘当量税额错误；所得税从已正确扣税后的利润出发，不是把销售额直接乘25%。",
      "rubric": [
        "增值8资源6",
        "当量1000环保0.12万元",
        "附加0.96各项正确",
        "所得5不重复扣税"
      ],
