      "chapterIndex": 12,
      "practiceStage": "cross",
      "knowledgePoint": "申报纠错、滞纳金、所得税与行政救济",
      "type": "written",
      "stem": "甲居民企业发现一笔少缴增值税40000元，本题已确认应补税且逾期20天，滞纳金日万分之五；年度会计利润1000000元已把税收滞纳金计入费用，税法不得扣除，其他无调整，所得税25%。税务机关另作一项独立罚款决定，题设该处罚争议可复议或直接诉讼。甲对税额确认无争议，仅对罚款有异议。要求：（1）算补税与滞纳金；（2）算所得税调增和年度税额；（3）提出纠错、证据保存和罚款救济路径，解释为何对罚款有异议不自动暂停补税。",
      "sample": "（1）补增值税40000元；滞纳金=40000×0.0005×20=400元，两项合计40400元。（2）滞纳金调增400元；应税所得1000400元，所得税250100元。（3）核对销售抵扣与申报资料，纠正申报并依法补缴；保存付款、决定和送达证据，针对独立罚款依法申请复议或提起诉讼。罚款争议与已确认的税款义务不同，不自动使缴税义务消失。",
      "explain": "补税及滞纳金计算、所得税税前扣除和处罚救济属于三个层次。易错点：滞纳金调增400不是增税400，增税为100；增值税补缴本题不直接作为所得税费用调减；未给罚款金额和入账情况，不能擅自加入所得税调整。",
      "rubric": [
        "补40000滞纳400合40400",
        "所得调增400税250100",
        "纠错凭证与罚款救济路径",
        "三类责任区分"
      ],
