      "type": "written",
      "stem": "启星教育原计划只销售录播课。对500名学员访谈后发现，他们更需要答疑服务；公司选择试办直播答疑，由教研部门培训教师并运行两个月，再根据续费率调整课程。老教师担心工作时间延长，学员希望晚间服务，投资人要求控制新增成本。要求：（1）把材料中的行动对应到战略管理过程；（2）提出两项协调利益相关者的具体行动，并说明如何支持创新实施。",
      "sample": "（1）访谈并识别需求属于战略分析；决定试办直播答疑属于战略选择；培训和试运行属于战略实施；根据续费率反馈调整体现动态管理和评价反馈。（2）与教师协商排班、培训和相应报酬，缓解额外负担并提高服务能力；向学员确认可接受时段，同时为投资人设定试点预算和扩张条件，使需求、成本与实施资源相衔接。",
      "explain": "按信息收集、方案决定、落地、反馈顺序定位，而非把全部行动归为实施。利益相关者方案要回应各自诉求，并形成可执行安排。易错点：续费率只能反映部分绩效，还应结合成本、服务质量；创新试点可以随反馈修正，不能等同于完全否定原战略。",
