      "knowledgePoint": "使命、战略层次与动态战略管理",
      "type": "written",
      "stem": "益邻集团以“让社区居民便捷获得可信赖的生活服务”为使命，现经营便利店。调研发现独居老人增多，集团决定新增社区配送业务；配送事业部承诺30分钟送达，信息部门建设调度系统。首月订单增长30%，但准时率只有70%，配送员加班严重。集团尚未制定明确目标。要求：（1）识别使命和三项决策的战略层次；（2）为配送业务设计两项可衡量目标并说明与使命的关系；（3）按战略管理过程提出下一轮调整步骤，兼顾顾客和员工。",
      "sample": "（1）使命说明企业的服务对象和存在理由。新增配送业务是总体战略；以30分钟送达形成竞争承诺是业务单位战略；建设调度系统是信息职能战略。（2）例如三个月内准时率达95%，同时平均每单投诉率低于2%；目标有期限和标准，支持便捷、可信赖的使命。（3）先分析延误时段、运力和员工负担，再选择缩小配送半径或分时容量管理；落实排班、培训和调度设置；持续检查准时率、投诉率及加班时长后修正。",
      "explain": "第一步按决策内容分层；第二步把抽象使命转成期限、指标、目标值；第三步形成分析—选择—实施—反馈的循环。提出目标值应明确是合理设计示例，不是材料已实现结果。易错点：订单增长不能证明战略整体成功；不能只要求员工加班来兑现承诺而忽略资源约束。",
      "rubric": [
        "使命和三层战略判断正确",
        "至少两项有期限指标目标值的目标",
        "调整步骤覆盖分析选择实施反馈",
        "兼顾顾客体验与员工负担"
      ],
