      "knowledgePoint": "创新战略执行、绩效评价与利益相关者权力",
      "type": "written",
      "stem": "远川设备拟以可回收材料替换原有包装。客户关注运输损坏率，采购部门担心材料涨价，生产部门担心设备不兼容；拥有关键模具技术的工程师不赞成直接全面换线。总经理提出先选一个产品试点，与两家材料供应商合作开发，试运行后再决定扩大。要求：（1）判断这项包装改进及外部合作的创新特征；（2）分析工程师影响决策的权力来源，以及应如何协调；（3）设计试点执行与评价方案，包含至少三类指标。",
      "sample": "（1）在既有产品和流程上改进包装可视为渐进创新；与外部供应商共同开发体现开放式创新。（2）工程师凭关键技术和专业知识形成影响力，应邀请其参加兼容性评估和试验设计，明确决策责任及可接受的质量标准。（3）设定试点产品、期限、预算和负责人，验证设备兼容性；评价运输损坏率、每件综合包装成本和可回收材料占比，并记录生产节拍变化；达到预设标准后逐步推广，否则修正材料或流程。",
      "explain": "创新类型依据改变幅度和知识来源判断，合作开发不自动意味着突破式创新。权力分析需要引用关键技术这一事实，协调方案要让专业意见进入决策。易错点：只看材料采购单价会遗漏损坏损失和设备调整成本；环保指标改善也不能掩盖质量下降。",
      "rubric": [
        "渐进创新与开放式创新判断并举证",
        "专业知识权力来源及协调安排",
        "执行方案有范围责任预算与试验",
        "评价覆盖质量成本环境并形成反馈"
      ],
