      "type": "written",
      "stem": "北城电动自行车企业遇到三项变化：当地发布充电设施安全要求；居民通勤距离缩短，短途骑行需求增加；两家电池供应商控制本地80%的电池供货，并要求提前付款。要求：（1）将前两项变化归入PEST因素并解释；（2）分析第三项对应的竞争力量及影响，提出一项采购应对。",
      "sample": "（1）充电设施安全要求属于政治与法律因素；居民生活和出行方式变化属于社会文化因素。（2）电池供应高度集中且供应商能改变付款条件，体现供应商议价能力较强，可能增加采购成本和资金占用；企业可开发合格备选供应商或与供应商建立长期供货协议，改善依赖程度。",
      "explain": "先区分宏观环境变化与产业交易关系，再依据集中度、替代来源和谈判条件分析竞争力量。易错点：安全要求会影响产业，但其来源仍是宏观法律环境；不能把电池供应商称为整车企业的买方；长期协议也需要质量与交付约束。",
