      "knowledgePoint": "总体战略、竞争战略与职能战略组合",
      "type": "written",
      "stem": "跃新电器现生产节能洗衣机，目标顾客重视安静运行和售后服务。公司拟在原有市场推出低噪音新机型，并收购本地维修连锁店。研发部门提出增加降噪测试，采购部门拟集中采购通用部件，营销部门拟承诺48小时上门服务，财务部门指出收购会在两年内占用较多现金。要求：（1）识别两项总体发展方案的类型；（2）判断适合的业务单位竞争方式，说明三项职能行动如何配合；（3）提出两项方案实施前应完成的评价，说明现金约束如何影响节奏。",
      "sample": "（1）向现有市场推出新机型属于产品开发；收购下游维修服务网络属于前向一体化。（2）依靠低噪音和可靠服务形成差异化。研发测试支持性能价值，采购通用非关键部件可控制成本但不能牺牲降噪，营销承诺须由维修网络和备件保障。（3）评价客户需求与支付意愿、连锁店服务质量和整合能力，并编制现金预算；可先试点新机型和服务，再分阶段收购或合作，避免资金不足影响经营。",
      "explain": "把总体战略和竞争方式分别判断，再检查研发、采购、营销之间是否互相支持。现金限制属于方案实施条件，不直接改变“产品开发”分类。易错点：进入售后环节不是后向一体化；服务承诺必须有产能和流程支撑；统一部件应保留顾客重视的关键差异。",
