      "type": "written",
      "stem": "拓源软件原来只做一个标准产品，采用职能制，审批集中在总经理。现有企业客户和个人客户两个业务线，需求变化快，但所有开发任务仍排在同一队列；部门绩效按各自成本考核，常把客户问题推给其他部门。要求：（1）分析现行结构和文化对新战略的障碍；（2）提出一项结构调整和一项协作机制，并说明预期作用。",
      "sample": "（1）业务需求分化后，共同任务队列和集中审批降低响应速度，职能壁垒及局部成本导向妨碍跨部门合作。（2）可设业务事业部或客户导向团队，给予明确的产品和服务决策权限；同时建立跨部门客户问题负责人、共享服务指标和升级流程，减少推诿并保留必要的技术标准。",
      "explain": "先用业务复杂度与响应要求检查结构匹配，再检查绩效和习惯是否支持合作。易错点：事业部制不意味着所有职能都要重复建设；仅改组织名称而不改权责和考核，不能消除协调障碍。",
