      "type": "written",
      "stem": "光成维修连锁本季度利润增加12%，但客户重复报修率由3%升至8%，技师培训时间下降，新预约客户等待时间延长。公司只用当期利润给店长发奖金。要求：（1）说明单一利润指标可能造成的问题；（2）从平衡计分卡四个维度各提出一项指标，并说明至少一条因果联系。",
      "sample": "（1）短期削减培训和服务成本可能提高利润，却损害服务质量和长期竞争能力。（2）财务：门店经营利润率；客户：满意度或重复报修率；内部业务流程：一次修复率或预约等待时间；学习与成长：技师技能培训达标率。培训改善技能，可能提高一次修复率、降低重复报修，进而改善满意度与长期收益。",
      "explain": "指标先分维度，再用材料建立业务因果链。易错点：重复报修率应关注降低；培训小时增加并不必然有效，应结合技能达标；同时考核四维度仍需合理权重，不能只把利润名称换掉。",
