      "type": "written",
      "stem": "安悦酒店计划用客户数据推荐套餐和预测客房需求。各分店客户编码不同，重复记录很多；业务部门认为转型只是买软件，员工担心系统评分不透明。试点店上线后空房减少，但推荐投诉增加。总部希望一年内推广，并把能源管理加入系统。要求：（1）识别至少三项转型障碍；（2）提出数据、组织与人才方面的实施方案；（3）设计试点评价与推广条件，兼顾客户、效率和可持续发展。",
      "sample": "（1）数据标准不一致、质量差，业务与技术脱节，员工缺乏理解或能力，推荐与客户需求不匹配。（2）统一客户编码和数据责任，先清理重复数据；由业务与技术共同定义需求和试点范围，培训员工并公开评分逻辑；设置必要的数据访问和隐私保护机制。（3）评价入住率或收益、推荐投诉率、预测准确度和每间已售客房能耗；达到数据质量、服务质量和节能标准后分阶段推广，未达标先调整。",
      "explain": "转型须连接业务问题与数据治理，组织保障不是软件采购的附属步骤。评价同时观察效率和负面影响。易错点：空房减少不能独立证明成功；投诉可能来自推荐方式而非数据量不够；能源指标应结合业务量，不能只用能源总量下降判断节能。",
      "rubric": [
        "至少三项材料中的障碍",
        "数据治理组织协同人才培训有责任安排",
        "评价至少覆盖客户效率环境",
        "推广以质量达标和反馈为条件"
      ],
