      "knowledgePoint": "大股东隧道行为与股东债权人冲突",
      "type": "written",
      "stem": "正川公司控股股东要求公司以高于市场的价格向其私人企业采购服务，且不提供定价说明。同时，公司拟为控股股东的高风险项目提供担保，现有债权人担心偿债能力下降。要求：（1）分别说明采购与担保可能涉及的治理冲突；（2）提出两项有针对性的治理安排。",
      "sample": "（1）不公允关联采购可能把公司资源转移给控股股东，损害中小股东，涉及隧道行为；高风险担保可能让股东受益而债权人承担额外风险，也存在大股东侵占问题。（2）建立独立审查、利益冲突申报及相关人员回避，提供市场定价证据和透明披露；对担保设置风险审查、限额和持续监控，并按适用约定保障债权人信息权。",
      "explain": "分析同一交易可影响不同利益相关者，不能强行只归一种冲突。易错点：关联交易并非必然不合法或不公允，题中高价且无说明是风险依据；措施依据治理原则提出，无需虚构具体法定审批比例。",
