      "knowledgePoint": "双重股权结构、数字治理与利益相关者",
      "type": "written",
      "stem": "智野平台创始人持有15%的股权，却通过不同表决权安排掌握60%的表决权。创始人希望持续投入研发，普通投资者担心缺少监督。平台拟用算法调整商户排名和服务费，规则不透明，商户申诉由算法开发团队自行处理。要求：（1）分析双重股权结构可能带来的收益与风险；（2）针对投资者保护提出两项治理安排；（3）分析算法决策涉及的利益相关者，并提出透明度和责任机制。",
      "sample": "（1）有助保留创始人的长期战略和研发投入能力；表决权与现金流权偏离可能削弱外部约束，增加利益侵占或管理固化风险。（2）可设置独立监督、重大利益冲突交易审查和充分披露，并在治理安排中明确特殊表决权的适用边界及复核机制。（3）涉及商户、消费者、平台员工和投资者。明确算法责任人、说明影响排名的主要规则、建立独立申诉和变更留痕，定期检查公平性及业务后果。",
      "explain": "先客观权衡控制稳定性与监督风险，再把数字技术的责任安排落到规则和申诉。易错点：15%持股不等于15%表决权；不能依据题设推断具体司法辖区的法定规定；“算法自动决定”不能免除管理和治理责任。",
      "rubric": [
        "双重股权收益风险各一项",
        "投资者保护至少两项可执行措施",
        "利益相关者至少两类",
        "算法透明申诉留痕与责任安排"
      ],
