      "knowledgePoint": "风险偏好、目标与全面风险管理",
      "type": "written",
      "stem": "新桥消费品公司考虑进入陌生市场。董事会愿意承担一定的销售波动以获取增长，但要求任一季度经营现金净流出不超过300万元。营销部门希望一次投入500万元广告，财务部门认为风险管理只需要买保险。要求：（1）解释增长意愿与现金约束分别表达什么；（2）说明保险为何不足以完成风险管理，并提出一个部门协同方案。",
      "sample": "（1）愿意为增长承担销售波动体现风险偏好；季度现金净流出上限是量化承受边界，应结合经营计划校验广告方案，而不能直接把投入额等同净流出。（2）保险主要处理部分可保风险，不能替代市场判断、资金安排和经营控制。营销、财务及运营共同评估需求、回款和供货，分阶段投放，滚动跟踪现金与市场反馈。",
      "explain": "偏好描述愿意承担风险的方向程度，约束需要落实到统一指标与期间。易错点：500万元广告投入不等于500万元现金净流出，还要考虑其他流入流出；全面风险管理包含战略与全过程，不能缩成灾后赔付。",
      "rubric": [
        "风险偏好与量化承受边界区分",
        "指出投入与现金净流出不是同一指标",
        "保险局限与跨部门方案"
      ],
