      "chapterIndex": 6,
      "practiceStage": "application",
      "knowledgePoint": "风险管理流程与关键风险指标",
      "type": "written",
      "stem": "开元批发发现本月客户逾期率上升。经理建议立刻停止所有赊销，但公司尚未区分客户、账龄和原因。现有数据可查合同期限、回款记录及客户投诉。要求：（1）说明风险解决方案形成前应完成的步骤；（2）提出两个关键风险指标及相应管理动作，避免一刀切。",
      "sample": "（1）先收集合同、回款、客户情况等初始信息；辨识逾期来源，分析发生可能性和影响；依据既定风险标准评价不同客户，再选择方案。（2）可监测逾期超过30天金额占应收款比率、单一客户信用敞口；超过经批准的预警界限时复核信用、催收或调整额度，对争议账款查明履约问题。阈值应经评估设定，本题未给出固定值。",
      "explain": "风险流程帮助把异常转为分级决策，指标要有明确口径和动作。易错点：逾期可能由合同争议或支付困难引起；不能在未评价前默认所有客户风险相同；监测指标并不能代替风险解决措施。",
      "rubric": [
        "初始信息辨识分析评价顺序清楚",
        "两个有定义的指标",
        "指标对应管理动作并区别客户"
      ],
