      "type": "written",
      "stem": "青岸仓储安装自动喷淋装置，并为存货购买火灾保险，合同约定免赔额10万元且不赔停业利润损失。经理认为此后不必再检查消防设备。要求：（1）判断两项措施的风险应对类型；（2）说明仍有哪些残余风险，并提出后续监督安排。",
      "sample": "（1）喷淋可降低火灾造成的损失，属于风险降低；保险把约定范围的经济后果转给保险人，属于风险转移。（2）免赔部分、停业利润损失、设备失效及保险除外责任等仍由企业承担。继续检修、演练和核对保障范围，监测存货价值变化及保险额度，评估残余风险是否在承受范围内。",
      "explain": "措施分类看它改变发生概率、后果还是承担主体，残余风险要结合合同条件。易错点：买保险不意味着火灾风险消失；免赔额不是企业最高损失限额；风险转移不解除日常防范责任。",
