      "knowledgePoint": "战略风险、市场风险与对应应对",
      "type": "written",
      "stem": "嘉陵照明准备全面转向高端智能灯具，却未调研客户需求，也未培养软件工程师。原有最大客户本月改向低价竞争者采购，企业仍按往年销量排产。要求：（1）分别识别新战略和原市场业务中的风险；（2）各提出一项针对性应对，并说明为何仅加大广告不足。",
      "sample": "（1）缺乏需求验证和软件资源导致战略制定、资源及实施风险；客户流失和照搬历史销量带来需求变化、竞争及市场洞察风险。（2）新业务先验证客户价值并补足技术人才、开展试点；旧业务持续收集客户流失原因和订单变化，调整产销及客户组合。广告不能修补产品价值不匹配、技术能力缺口或排产失真。",
      "explain": "同一材料可能同时体现战略与市场风险，应按决策层级与风险来源展开。易错点：进入高端市场不必然错误，问题在未经验证且能力不足；失去大客户不只能归为财务问题，应识别需求和竞争成因。",
