      "type": "written",
      "stem": "瑞锋设备用三个月到期的借款建设预计两年回收的厂房；销售团队为了冲销量，允许新客户半年后付款，且没有信用审查。一个月后企业订单充足却无法支付原料款。要求：（1）识别两类财务风险及有关运营控制缺陷；（2）提出融资和销售收款方面的改进。",
      "sample": "（1）短期资金支持长期项目存在期限错配和续借压力，属于筹资管理风险；信用销售造成资金占用和回款不确定，属于资金营运风险；销售业务缺少信用审查及收款控制。（2）匹配项目资金期限，编制滚动现金预算并保留流动性；建立客户分级、信用额度、账龄监测和催收流程，避免仅以订单量考核。",
      "explain": "将融资结构、现金循环和业务控制分别定位。易错点：订单多不等于现金充足；续借不是确定的资金来源；不应只靠立即削减所有销售来处理现金缺口，应基于信用与现金判断。",
