      "knowledgePoint": "国际化选择、环境风险与现金控制跨章案例",
      "type": "written",
      "stem": "合川农机拟进入乙国。乙国农户土地较小，需要小型机具；当地两家经销商控制主要渠道，进口审批流程变化较快。合川的核心发动机可统一生产，但外观和配件需适应当地需求。公司考虑直接出口或与当地制造商合作，销售以乙国货币结算且回款较慢。要求：（1）分析外部环境与渠道竞争压力；（2）提出兼顾整合与响应的国际化战略、进入方式建议；（3）识别至少三项风险并提出对应措施；（4）说明决策前需要补充哪些初始信息，如何分阶段实施。",
      "sample": "（1）审批变化属于政治法律环境；经销商集中提高渠道议价压力；土地规模构成本土需求差异。（2）统一核心发动机、适配机具并兼顾两种压力，可采用跨国战略方向；进入方式需比较出口成本控制与合作伙伴能力、控制权，可先小规模出口或合作试点。（3）审批和合作合规风险：核实制度和合同；汇率市场风险：评估敞口并采取适当结算或套期安排；回款营运风险：信用审查、额度和催收；渠道依赖：开发替代渠道。（4）收集需求、审批、伙伴能力、汇率回款和成本数据，设试点标准后扩张。",
      "explain": "国际化战略与进入方式分别作判断，风险措施必须匹配来源。易错点：乙国货币结算只说明有汇率敞口，不足以推断必然亏损；不能凭题设虚构当地审批法规；套期可能降低波动，但不保证零风险和无成本。",
      "rubric": [
        "宏观环境和渠道力量分析",
        "战略方向与进入方式权衡",
        "至少三项风险有措施",
        "初始信息与分阶段条件清楚"
      ],
