      "chapterIndex": 3,
      "practiceStage": "cross",
      "knowledgePoint": "商业模式创新、数智化实施与数字治理跨章案例",
      "type": "written",
      "stem": "蓝途零售原先只经营实体商店，计划开展会员订阅配送，依靠商品推荐和定期补货形成收入。总部拟统一算法，各店仍使用不同商品编码；员工奖金仅按现场销售额，拒绝处理配送订单。公司准备将全部会员数据交给外部开发商，合同未写数据边界；顾客发现取消订阅入口难找，投诉增加。要求：（1）识别商业模式变化及关键能力；（2）分析组织激励和数据障碍，提出实施安排；（3）分析数字治理与外包风险，提出至少三项控制；（4）设计包含财务、客户、流程、学习成长的评价。",
      "sample": "（1）从一次性销售扩展到订阅和配送收入，需要需求预测、履约、推荐与客户服务能力。（2）统一商品编码和数据责任；明确门店与配送职责，把履约与客户指标加入考核，培训员工并先试点。（3）限定开发商数据用途和访问权限，开展尽调和独立监督，建立安全审计及事故通知；明确算法责任，提供可理解推荐规则和便捷取消申诉。（4）财务看会员业务现金与贡献，客户看留存和投诉，流程看准时率与订单准确率，学习成长看数据及履约技能达标。",
      "explain": "商业模式说明怎样创造和取得价值，数智化要有数据和业务支持，治理要有明确责任与可纠错渠道。易错点：订阅人数增长不能掩盖取消困难造成的虚假留存；总收入不能替代订阅贡献；外包合同不能替代实际权限控制。",
