      "type": "written",
      "stem": "景创出口家具主要销售给一个境外平台，该平台占收入70%，以外币付款，付款期90天。平台计划提高佣金，国际运输价格波动，企业以短期借款补充周转。生产团队仍按原销售量采购，财务经理建议只购买财产保险。要求：（1）识别市场、财务和运营风险并解释相互传导；（2）提出渠道与客户方面的竞争应对；（3）设计现金与汇率风险控制；（4）说明应收集的数据、预警指标和保险方案的局限。",
      "sample": "（1）单一平台依赖、佣金与汇率运输价格变化形成市场风险；长账期和短借款造成资金营运及筹资压力；采购不随需求调整可能积压库存。佣金或销量变化会影响回款和现金，再影响偿债。（2）发展多渠道和客户组合，谈判服务与收费，评估差异化产品价值而非盲目降价。（3）滚动现金预算覆盖销售、回款、采购和借款到期，保留缓冲；识别净外币敞口，评估匹配收支、结算条款或适当套期。（4）收集渠道占比、逾期、汇率、运费和库存，跟踪现金缺口与集中度；财产保险不能覆盖全部需求或流动性风险。",
      "explain": "风险传导要从业务条件走到现金后果，汇率控制以净敞口为基础。易错点：外币收入上涨不一定造成损失，需说明方向；套期工具需匹配业务而非投机；财产保险无法替代渠道和资金管理。",
      "rubric": [
        "三类风险及至少一条传导链",
        "渠道客户或差异化应对具体",
        "现金预算与敞口控制匹配业务",
        "数据指标与保险局限"
      ],
